ArrayList<Part> parts;
let noiseoff=0.0;
let c1 = "#01A503"; 
let c2 = "#C164B0";
let coloroff=random(255);
let record=false;

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL); 
  smooth();
  frameRate(25);
  parts = new ArrayList();
}

function paint( x,  y,  dx,  dy,  size,  parent,  bymouse) {
  let tx = x;
  let ty = y;

  let t=15+random(20);
  let c = lerpColor(c1, c2, random(1)); 
  coloroff++;
  if (coloroff>255) {
    coloroff=0;
  }

  var c = color(0, 200, coloroff); 
  let p = new Part(tx, ty, size, c);
  if (!bymouse) {
    p.c=parent.c;
  }
  p.velocity.x=0;
  p.velocity.y=0;
  if (dy == 0 && dx == 0) {
     dx=random(1)-.5; 
     dy=random(1)-.5;
  }
  p.acceleration.x=dx;
  p.acceleration.y=dy; 
  p.or_a.x = dx;
  p.or_a.y = dy;
  p.par=parent;

  parts.add(p);
  return p;
}
let lastp=null;

function drawGradientBackground() {
  let colorA = color(10, 10, 50);
  let colorB = color(137, 189, 222);
  let colorC = color(255);
  let splitY = height * 0.7;

  for (y = 0; y < height; y++) {
    var t;
    if (y < splitY) {
      t = y / splitY;
      stroke(lerpColor(colorA, colorB, t));
    } else {
      t = (y - splitY) / (height - splitY);
      stroke(lerpColor(colorB, colorC, t));
    }
    line(0, y, width, y);
  }
}
function draw() {
  noStroke();
	drawGradientBackground();
  if (record) {
    lastp=paint((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), ((window.simulatedPMouseX !== undefined ? window.simulatedPMouseX : (typeof sub_bass_prev !== 'undefined' ? map(sub_bass_prev, 0, 1, width*0.1, width*0.9) : (typeof window.simulatedMouseX !== 'undefined' ? window.simulatedMouseX - 12 : pmouseX)))-(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))))*-.1, ((window.simulatedPMouseY !== undefined ? window.simulatedPMouseY : (typeof percussive_prev !== 'undefined' ? map(percussive_prev, 0, 1, height, 0) : (typeof window.simulatedMouseY !== 'undefined' ? window.simulatedMouseY - 12 : pmouseY)))-(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))))*-.1, random(9), lastp, true);
  }
  else {
    lastp=null;
  }
  updateParticles();
}
function mousePressed() {
  record=true;
}
function mouseReleased() {
  record=false;
}

function rotate2D(v, theta) {
	let xTemp = v.x;
  v.x = v.x*cos(theta) - v.y*sin(theta);
  v.y = xTemp*sin(theta) + v.y*cos(theta);
}

function updateParticles() {
  if (parts.size()>0) {
    noiseoff+=.1;
    let s = parts.size()-1;
    for (i = s; i >= 0; i--) {
      var p = (Part) parts.get(i);      
      p.update();
      if (p.life<0) {
        parts.remove(p);
      }    
      if (p.life<.9 && p.spawned<25 && parts.size()<650 && p.life>.5) {
        p.spawned++;
        if (random(1)>.9) {
          let dir = p.or_a;
          dir.normalize();
          rotate2D(dir, radians(random(45)-22.5));

          dir.mult(3);
          let np = paint(p.position.x, p.position.y,dir.x, dir.y, p.size*.9, p, false);
          np.spawned=p.spawned;
        }
      }
      stroke(p.c, 5+p.life*255);
      strokeWeight(noise(i+noiseoff)*3);

      if (p.par!=null) {
        line(p.position.x, p.position.y, p.par.position.x, p.par.position.y);
      }
      p.render();
    }
  }
}

class Part {
  par=null;
  spawned = 0;
  life = 1;
  maxspeed=10;
  let r=random(360);
  let position = new PVector(0, 0);
  let velocity = new PVector(0, 0);
  let acceleration = new PVector(0, 0);
  let or_a = new PVector(0, 0);
  size = 6;
  c;

  constructor(x, y, size, c) {
    position.x=x;
    position.y=y;
    this.size = size;
    this.c=c;
  }
  function update() {
    life-=.01;
    velocity.add(acceleration);
    velocity.limit(15);
    velocity.mult(.95);
    position.add(velocity);

    acceleration.mult(0);
  }
  function render() {    
    pushMatrix();
    translate(position.x, position.y);
    rotate(radians(r));
    noStroke();

    fill(c);
    noFill();
    ellipse(0, 0, size, size);
    stroke(c, 3+life*255);
    noFill();
    ellipse(0, 0, size*3, size*3);

    popMatrix();
  }
  function applyForce(force) {
    acceleration.add(force);
  }
}

